import re,pathlib
# Parse static c_asn1 table counts and local arrays. Find sc_copy_asn1_entry(template, local) where local capacity < template count.
texts={p: p.read_text(errors='ignore') for p in pathlib.Path('src').rglob('*.c')}
counts={}
macros={}
for p,s in texts.items():
 for m in re.finditer(r'#define\s+(\w+)\s+(\d+)', s): macros[m.group(1)]=int(m.group(2))
for p,s in texts.items():
 for m in re.finditer(r'(?:static\s+)?(?:const\s+)?struct\s+sc_asn1_entry\s+(c_asn1_\w+|g_\w+)\s*(?:\[([^\]]*)\])?\s*=\s*\{', s):
  name,sz=m.group(1), (m.group(2) or '').strip(); start=m.end(); depth=1; i=start
  while i<len(s) and depth:
   if s[i]=='{': depth+=1
   elif s[i]=='}': depth-=1
   i+=1
  body=s[start:i-1]
  cnt=len(re.findall(r'^\s*\{',body,re.M))
  # actual entries inc sentinel if present
  counts[name]=cnt
# scan functions declaration chunks preceding sc_copy
for p,s in texts.items():
 for cm in re.finditer(r'sc_copy_asn1_entry\(\s*(\w+)\s*,\s*(\w+)\s*\)', s):
  tmpl,loc=cm.group(1),cm.group(2)
  # find capacity declaration for loc in preceding 5000 chars
  pre=s[max(0,cm.start()-6000):cm.start()]
  cap=None
  # all matches, take last declaration occurrence
  for dm in re.finditer(r'struct\s+sc_asn1_entry\s+([^;]*\b'+re.escape(loc)+r'\s*\[([^\]]+)\][^;]*);', pre):
   sz=dm.group(2).strip()
   cap=int(sz) if sz.isdigit() else macros.get(sz)
  cnt=counts.get(tmpl)
  if cnt and cap and cnt>cap:
   print('COPY OOB',p, 'line',s.count('\n',0,cm.start())+1, tmpl,cnt,'->',loc,cap)
PY

